package com.complaintbox.controller; import com.complaintbox.dto.ComplaintDtos.*; import com.complaintbox.service.*; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/complaints") public class ComplaintController{final ComplaintService service;final AuthService auth;public ComplaintController(ComplaintService s,AuthService a){service=s;auth=a;}@PostMapping public Object create(@RequestBody Create x,HttpSession s){return service.map(service.create(auth.residentId(s),x));}@GetMapping("/my")public Object my(HttpSession s){return service.mine(auth.residentId(s)).stream().map(service::map).toList();}@GetMapping("/{id}")public Object one(@PathVariable Long id,HttpSession s){Object role=s.getAttribute("ROLE");Map<String,Object>d=service.detail(id);if("STUDENT".equals(role)){Long rid=auth.residentId(s);if(!service.get(id).getResident().getId().equals(rid))throw new RuntimeException("Complaint not found");}return d;}}
